glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
uniform Constant {
  mat4 worldInvertMat;
  vec4 showTextureRange;
  vec2 nodeSize;
  vec2 nodeAnchor;
  vec2 uvRange;
  vec2 showUvRange;
  vec2 rowUvOffset;
  vec2 uvMoveSpeed;
  float brightness;
  float useInvertMat;
};
out vec2 v_uv0_fix;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  if (useInvertMat > 0.0) {
    vec4 localPos = worldInvertMat * vec4(a_position, 1);
    float uv0FixX = (localPos.x + nodeSize.x * nodeAnchor.x) / nodeSize.x;
    float uv0FixY = 1.0 - (localPos.y + nodeSize.y * nodeAnchor.y) / nodeSize.y;
    v_uv0_fix = vec2(uv0FixX, uv0FixY);
  } else {
    v_uv0_fix = a_uv0;
  }
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 v_color;
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
uniform sampler2D detailTexture;
uniform Constant {
  mat4 worldInvertMat;
  vec4 showTextureRange;
  vec2 nodeSize;
  vec2 nodeAnchor;
  vec2 uvRange;
  vec2 showUvRange;
  vec2 rowUvOffset;
  vec2 uvMoveSpeed;
  float brightness;
  float useInvertMat;
};
in vec2 v_uv0_fix;
#endif
void main () {
  vec4 o = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    o.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    o.a *= texture_tmp.a;
  #else
    o *= texture_tmp;
  #endif
  #endif
  o *= v_color;
  ALPHA_TEST(o);
  #if USE_BGRA
    gl_FragColor = o.bgra;
  #else
    gl_FragColor = o.rgba;
  #endif
}

